import os

def scan_directory(path, max_depth=5, current_depth=0):
    items = []
    if current_depth >= max_depth:
        return items

    try:
        for item in os.listdir(path):
            item_path = os.path.join(path, item)
            try:
                if os.path.isfile(item_path):
                    size = os.path.getsize(item_path)
                    items.append(('FILE', item_path, size))
                elif os.path.isdir(item_path):
                    items.append(('DIR', item_path, 0))
                    items.extend(scan_directory(item_path, max_depth, current_depth + 1))
            except:
                pass
    except:
        pass

    return items

# Scan project directory
print("=== PROJECT DIRECTORY ===")
project_items = scan_directory('project')
for itype, path, size in project_items:
    if itype == 'FILE':
        print(f"{path} ({size} bytes)")
    else:
        print(f"{path}/")

